const tree = root => { const out = {}; const walk = (dir, at) => { for (const e of fs.readdirSync(dir, { withFileTypes: true })) { const p = dir + "/" + e.name, k = at + e.name;
  if (e.isSymbolicLink()) out[k] = "link -> " + fs.readlinkSync(p); else if (e.isDirectory()) { out[k] = "dir"; walk(p, k + "/"); } else out[k] = "file:" + fs.readFileSync(p, "utf8"); } }; walk(root, ""); return out; };
// tmpfs lists a directory newest first, so each directory's entries are created in descending name order: Node then walks
// them in the byte order the file service lists in.
const seed = root => { fs.mkdirSync(root + "/d/sub", { recursive: true }); fs.symlinkSync("a", root + "/d/rel"); fs.symlinkSync("/work/" + root + "/d/sub", root + "/d/abs"); fs.writeFileSync(root + "/d/a", "A"); fs.writeFileSync(root + "/d/sub/b", "B");
  fs.writeFileSync(root + "/f", "F"); fs.symlinkSync("f", root + "/lf"); fs.symlinkSync("d", root + "/ld"); fs.symlinkSync("missing", root + "/dangling"); fs.symlinkSync("old", root + "/lold");
  fs.writeFileSync(root + "/old", "OLD"); fs.mkdirSync(root + "/ed/sub", { recursive: true }); fs.writeFileSync(root + "/ed/keep", "K"); fs.writeFileSync(root + "/ed/a", "old-a");
  fs.mkdirSync(root + "/clash"); fs.mkdirSync(root + "/clash/a"); fs.writeFileSync(root + "/clash/sub", "S"); fs.mkdirSync(root + "/links"); fs.symlinkSync("elsewhere", root + "/links/rel"); fs.symlinkSync("/work/" + root + "/ed", root + "/links/abs"); };
const calls = [];
const cases = {
  fileNew: r => [r + "/f", r + "/out"], fileOverwrite: r => [r + "/f", r + "/old"], fileNoForce: r => [r + "/f", r + "/old", { force: false }],
  fileErrorOnExist: r => [r + "/f", r + "/old", { force: false, errorOnExist: true }], fileErrorOnExistForce: r => [r + "/f", r + "/old", { errorOnExist: true }],
  dirNoRecursive: r => [r + "/d", r + "/out"], dirRecursive: r => [r + "/d", r + "/out", { recursive: true }], dirMerge: r => [r + "/d", r + "/ed", { recursive: true }],
  dirMergeNoForce: r => [r + "/d", r + "/ed", { recursive: true, force: false }], dirMergeErrorOnExist: r => [r + "/d", r + "/ed", { recursive: true, force: false, errorOnExist: true }],
  dirToFile: r => [r + "/d", r + "/old", { recursive: true }], fileToDir: r => [r + "/f", r + "/ed"], same: r => [r + "/f", r + "/f"], sameDir: r => [r + "/d", r + "/d", { recursive: true }],
  intoSelf: r => [r + "/d", r + "/d/sub/copy", { recursive: true }], intoSelfNoRecursive: r => [r + "/d", r + "/d/sub/copy"], missing: r => [r + "/nope", r + "/out"], missingRecursive: r => [r + "/nope", r + "/out", { recursive: true }],
  nestedDest: r => [r + "/f", r + "/x/y/z/out"], nestedDestDir: r => [r + "/d", r + "/x/y/out", { recursive: true }], destUnderFile: r => [r + "/f", r + "/old/out"],
  linkFile: r => [r + "/lf", r + "/out"], linkFileVerbatim: r => [r + "/lf", r + "/out", { verbatimSymlinks: true }], linkFileDereference: r => [r + "/lf", r + "/out", { dereference: true }],
  linkDir: r => [r + "/ld", r + "/out"], linkDirRecursive: r => [r + "/ld", r + "/out", { recursive: true }], linkDirDereference: r => [r + "/ld", r + "/out", { recursive: true, dereference: true }],
  dangling: r => [r + "/dangling", r + "/out"], danglingDereference: r => [r + "/dangling", r + "/out", { dereference: true }],
  linkOverFile: r => [r + "/lf", r + "/old"], linkOverLink: r => [r + "/lf", r + "/ld"], fileOverLink: r => [r + "/f", r + "/lf"],
  dirVerbatim: r => [r + "/d", r + "/out", { recursive: true, verbatimSymlinks: true }], dirDereference: r => [r + "/d", r + "/out", { recursive: true, dereference: true }],
  filter: r => [r + "/d", r + "/out", { recursive: true, filter: (s, d) => { calls.push([s, d]); return !s.endsWith("/a") && !s.endsWith("/abs"); } }],
  filterRoot: r => [r + "/d", r + "/out", { recursive: true, filter: () => false }], filterTruthy: r => [r + "/f", r + "/out", { filter: () => 1 }],
  filterPromise: r => [r + "/d", r + "/out", { recursive: true, filter: () => Promise.resolve(true) }], filterPromiseFalse: r => [r + "/d", r + "/out", { recursive: true, filter: s => Promise.resolve(!s.endsWith("/a")) }],
  filterNested: r => [r + "/d", r + "/out", { recursive: true, filter: s => s.endsWith("/sub") ? Promise.resolve(true) : true }], filterThrows: r => [r + "/d", r + "/out", { recursive: true, filter: () => { throw new RangeError("no"); } }],
  filterMerge: r => [r + "/d", r + "/ed", { recursive: true, filter: () => true }], filterMergeErrorOnExist: r => [r + "/d", r + "/ed", { recursive: true, force: false, errorOnExist: true, filter: () => true }],
  modeExcl: r => [r + "/f", r + "/old", { mode: 1 }], modeExclNew: r => [r + "/f", r + "/out", { mode: 1 }], modeBad: r => [r + "/f", r + "/out", { mode: 8 }], modeText: r => [r + "/f", r + "/out", { mode: "1" }],
  optionsText: r => [r + "/f", r + "/out", "x"], optionsNull: r => [r + "/f", r + "/out", null], recursiveText: r => [r + "/f", r + "/out", { recursive: "yes" }], forceNumber: r => [r + "/f", r + "/out", { force: 1 }],
  pair: r => [r + "/f", r + "/out", { dereference: true, verbatimSymlinks: true }], filterText: r => [r + "/f", r + "/out", { filter: "x" }], srcType: r => [5, r + "/out"], destType: r => [r + "/f", 5], srcNul: r => ["a\0", r + "/out"],
  url: r => [new URL("file:///work/" + r + "/f"), new URL("file:///work/" + r + "/out")], buffer: r => [h.Buffer.from(r + "/f"), h.Buffer.from(r + "/out")], trailingSlash: r => [r + "/d/", r + "/out/", { recursive: true }],
  missingDereference: r => [r + "/nope", r + "/out", { dereference: true }], derefFileOverLinkToDir: r => [r + "/f", r + "/ld", { dereference: true }], derefDirOverLinkToFile: r => [r + "/d", r + "/lf", { recursive: true, dereference: true }],
  derefFileOverLink: r => [r + "/f", r + "/lold", { dereference: true }], derefLinkRecursive: r => [r + "/lf", r + "/out", { recursive: true, dereference: true }], derefLinkDirOverFile: r => [r + "/ld", r + "/old", { recursive: true, dereference: true }],
  throughLink: r => [r + "/d", r + "/ld/x", { recursive: true }], overLinks: r => [r + "/d", r + "/links", { recursive: true }], overLinksNoForce: r => [r + "/d", r + "/links", { recursive: true, force: false }], overLinksVerbatim: r => [r + "/d", r + "/links", { recursive: true, verbatimSymlinks: true }],
  clash: r => [r + "/d", r + "/clash", { recursive: true }], clashFilter: r => [r + "/d", r + "/clash", { recursive: true, filter: () => true }], overLinksFilter: r => [r + "/d", r + "/links", { recursive: true, filter: () => true }],
  fileIntoLinkedDir: r => [r + "/f", r + "/ld/new"], noForceLink: r => [r + "/lf", r + "/lold", { force: false, errorOnExist: true }], dirErrorOnExistForce: r => [r + "/d", r + "/ed", { recursive: true, errorOnExist: true }],
  linkToParent: r => [r + "/ld", r + "/d/sub/l", { recursive: true }],
  dotSegments: r => [r + "/d/../f", r + "/./out"], dirOverLinkToDir: r => [r + "/d", r + "/ld", { recursive: true }],
};
const out = { shapes: [h.fn(fs.cpSync), h.fn(fs.cp), h.fn(fs.promises.cp)] };
for (const [name, build] of Object.entries(cases)) {
  const result = {};
  for (const kind of ["sync", "promise"]) {
    const root = name + "-" + kind; fs.mkdirSync(root); seed(root); const before = JSON.stringify(tree(root)); calls.length = 0;
    const args = build(root);
    const answer = kind === "sync" ? h.attempt(() => fs.cpSync(...args)) : await h.attemptAsync(() => fs.promises.cp(...args));
    const after = tree(root);
    result[kind] = { answer, tree: JSON.stringify(after) === before ? "unchanged" : Object.fromEntries(Object.entries(after).filter(([k, v]) => JSON.parse(before)[k] !== v)), ...(calls.length ? { calls: calls.slice() } : {}) };
  }
  out[name] = result;
}
return out;

