fs.writeFileSync("f", "F"); fs.chmodSync("f", 0o640); fs.utimesSync("f", 1000, 2000); fs.writeFileSync("ro", "R"); fs.chmodSync("ro", 0o444); fs.utimesSync("ro", 3000, 4000);
fs.mkdirSync("d/sub", { recursive: true }); fs.writeFileSync("d/a", "A"); fs.chmodSync("d/a", 0o600); fs.utimesSync("d/a", 5000, 6000); fs.chmodSync("d/sub", 0o700); fs.chmodSync("d", 0o750); fs.utimesSync("d", 7000, 8000);
const meta = p => { const s = fs.statSync(p); return [(s.mode & 0o777).toString(8), s.mtimeMs / 1000 < 1e6 ? s.mtimeMs / 1000 : "now"]; };
const out = {};
fs.cpSync("f", "plain"); out.plain = meta("plain");
fs.cpSync("f", "kept", { preserveTimestamps: true }); out.kept = meta("kept");
fs.cpSync("ro", "roKept", { preserveTimestamps: true }); out.readOnly = meta("roKept");
fs.writeFileSync("existing", "old"); fs.chmodSync("existing", 0o666); fs.cpSync("f", "existing"); out.overwritten = [meta("existing")[0], fs.readFileSync("existing", "utf8")];
fs.writeFileSync("existing2", "old"); fs.cpSync("f", "existing2", { preserveTimestamps: true }); out.overwrittenKept = meta("existing2");
fs.cpSync("d", "dPlain", { recursive: true }); out.dirPlain = [meta("dPlain"), meta("dPlain/a"), meta("dPlain/sub")];
fs.cpSync("d", "dKept", { recursive: true, preserveTimestamps: true }); out.dirKept = [meta("dKept"), meta("dKept/a"), meta("dKept/sub")];
fs.cpSync("d", "dFiltered", { recursive: true, preserveTimestamps: true, filter: () => true }); out.dirFiltered = [meta("dFiltered"), meta("dFiltered/a"), meta("dFiltered/sub")];
return out;

