fs.writeFileSync("f", "F"); fs.chmodSync("f", 0o640); fs.utimesSync("f", 1000, 2000); fs.writeFileSync("ro", "R"); fs.chmodSync("ro", 0o444); fs.utimesSync("ro", 3000, 4000);
fs.mkdirSync("d/sub", { recursive: true }); fs.writeFileSync("d/a", "A"); fs.chmodSync("d/a", 0o600); fs.utimesSync("d/a", 5000, 6000); fs.chmodSync("d/sub", 0o700); fs.chmodSync("d", 0o750); fs.utimesSync("d", 7000, 8000);
const meta = p => { const s = fs.statSync(p); return [(s.mode & 0o777).toString(8), s.mtimeMs / 1000 < 1e6 ? s.mtimeMs / 1000 : "now"]; };
const out = {};
await fs.promises.cp("f", "pKept", { preserveTimestamps: true }); out.promiseKept = meta("pKept");
await fs.promises.cp("d", "pdKept", { recursive: true, preserveTimestamps: true }); out.promiseDirKept = [meta("pdKept"), meta("pdKept/a"), meta("pdKept/sub")];
out.callback = await new Promise(resolve => { const order = []; const r = fs.cp("f", "viaCallback", (...args) => { order.push("callback"); resolve({ order, args, r }); }); order.push("returned"); });
out.callbackOptions = await new Promise(resolve => fs.cp("d", "viaCallbackDir", { recursive: true }, (...args) => resolve([args, fs.readFileSync("viaCallbackDir/a", "utf8")])));
out.callbackError = await new Promise(resolve => fs.cp("nope", "x", e => resolve(h.err(e))));
out.callbackMissing = h.attempt(() => fs.cp("f", "x")); out.callbackValidation = h.attempt(() => fs.cp("f", "x", { recursive: 1 }, () => {}));
return out;
